def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    prev_bids = []
    desperate_count = 0
    rich_aggressive = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
                desperate_count += 1
            if opp.get('budget', 0) >= 700:
                prev = opp.get('previous_trace', {})
                if prev and prev.get('bid') is not None and prev.get('bid') >= 80:
                    rich_aggressive += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                prev_bids.append(prev.get('bid'))

    if budget <= 0:
        return 0.0

    if not alive_opponents:
        return float(min(budget, 18.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0

    danger = 0
    if hp <= 2:
        danger += 3
    elif hp <= 4:
        danger += 2
    elif hp <= 6:
        danger += 1
    if no_water_days >= 2:
        danger += 3
    elif no_water_days >= 1:
        danger += 1

    if danger >= 5:
        bid = max(95.0, highest_prev + 3.0)
    elif danger >= 3:
        bid = max(72.0, min(98.0, highest_prev + 2.0))
    else:
        if supply >= 22:
            bid = 18.0
        elif supply >= 19:
            bid = 26.0
        elif supply >= 17:
            bid = 38.0
        else:
            bid = 52.0

        if highest_prev > 0:
            if highest_prev <= 65:
                bid = max(bid, highest_prev + 1.5)
            elif highest_prev <= 95:
                bid = max(bid, min(highest_prev + 1.0, 68.0))
            else:
                bid = max(24.0, bid - 6.0)

        bid += scarcity * 10.0
        bid += desperate_count * 1.5
        if rich_aggressive >= 2 and hp > 4 and no_water_days == 0:
            bid -= 5.0

    if day >= 8:
        bid += 6.0
    if day >= 9 and (hp <= 5 or no_water_days >= 1):
        bid += 10.0

    reserve = 0.0
    if hp > 4 and no_water_days == 0:
        reserve = DAILY_SALARY * 1.2
    elif hp > 2:
        reserve = DAILY_SALARY * 0.6

    max_affordable = max(0.0, budget - reserve)
    if danger >= 3:
        max_affordable = budget

    bid = min(bid, max_affordable if max_affordable > 0 else budget)
    bid = min(bid, budget)
    if bid < 0:
        bid = 0.0

    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10 

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    if not alive_opponents:
        return max(0.01, min(my_status['budget'], DAILY_SALARY * 0.2))

    if my_status['hp'] <= 2:
        return max(0.01, min(my_status['budget'], DAILY_SALARY * 0.98))
    if my_status['no_water_days'] > 0:
        return max(0.01, min(my_status['budget'], DAILY_SALARY * 0.9))

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    current_bid = DAILY_SALARY * 0.6

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        if highest_prev_bid >= DAILY_SALARY * 0.8:
            if my_status['hp'] > 5:
                current_bid = max(current_bid, highest_prev_bid * 1.05)
            else:
                current_bid = max(current_bid, highest_prev_bid + 10)
        elif highest_prev_bid >= DAILY_SALARY * 0.5:
            current_bid = max(current_bid, highest_prev_bid + 5)
        else:
            current_bid = max(current_bid, highest_prev_bid + 15)

    supply_units = day_context['supply'] / WATER_REQ

    if supply_units < 2:
        current_bid *= 1.15
    elif day_context['supply'] < (num_alive_opponents + 1) * WATER_REQ:
        current_bid *= 1.25
    elif supply_units > num_alive_opponents + 2:
        current_bid *= 0.9

    remaining_days = EPISODE_DAYS - day_context['day']
    if remaining_days <= 2:
        if my_status['hp'] < 5:
            current_bid = max(current_bid, DAILY_SALARY * 0.9)
        else:
            current_bid = max(current_bid, DAILY_SALARY * 0.5)

    current_bid = max(current_bid, DAILY_SALARY * 0.3)

    final_bid = min(my_status['budget'], current_bid)
    return max(0.01, final_bid)

